import { spawn as nodeSpawn } from 'node:child_process'
import fs from 'node:fs'
import { createRequire } from 'node:module'
import net from 'node:net'

import * as ChildProcessSpawner from 'effect/unstable/process/ChildProcessSpawner'

/**
 * Resolve the worker entry through the package's `exports` subpaths.
 *
 * `package.json` keeps explicit worker subpaths (`./child-process-proxy-worker-main`,
 * `./checker-worker`, `./child-process-test-runner-worker`) generated by `tsdown`
 * (`tsdown.config.ts` entry `child-process-proxy-worker-main` → `dist/child-process-proxy-worker-main.mjs`).
 * The `default` export condition points to the built `dist/*.mjs`; the
 * `@systemfsoftware/source` condition points to `src/...ts`. `node` can run the
 * built output directly, but under `vitest` (source, no build) the same specifier
 * would resolve to the `.ts` source, which needs type stripping. This helper
 * isolates that difference so no call site carries a bare `.mjs` guess.
 */
export const resolveWorkerMainPath = (): string => {
  // Try the package exports first — works when `dist/` exists (real run or
  // `pnpm build` has been run). Under `vitest` without a build, the `dist`
  // file may be absent, so fall back to the source file which
  // `node --experimental-strip-types` can execute. Branch lives here, not at
  // each spawn site.
  try {
    const require = createRequire(import.meta.url)
    const resolved = require.resolve('@systemfsoftware/stryker-js-mutation-run/child-process-proxy-worker-main')
    if (fs.existsSync(resolved)) return resolved
  } catch {
    // fall through to source fallback
  }
  return new URL('./child-process-proxy-worker-main.ts', import.meta.url).pathname
}

export { ChildProcessSpawner, net, nodeSpawn }
